import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";import{K as i}from"./chunks/assets.DeBnt35C.js";var a=JSON.parse(`{"title":"运行原理","description":"","frontmatter":{},"headers":[],"relativePath":"middleware/docker/basic/principle.md","filePath":"middleware/docker/basic/principle.md"}`),o={name:`middleware/docker/basic/principle.md`};function s(r,a,o,s,c,l){return n(),e(`div`,null,[...a[0]||=[t(`<h1 id="运行原理" tabindex="-1">运行原理 <a class="header-anchor" href="#运行原理" aria-label="Permalink to “运行原理”">​</a></h1><ul><li>用户是使用Docker Client与Docker Daemon建立通信，并发送请求给后者。</li><li>Docker Daemon作为Docker架构中的主体部分，首先提供Docker Server的功能使其可以接受Docker Client的请求。</li><li>Docker Engine执行Docker内部的一系列工作，每一项工作都是以一个Job的形式的存在。</li><li>Job的运行过程中，当需要容器镜像时，则从Docker Registry中下载镜像，并通过镜像管理驱动Graph driver将下载镜像以Graphe的形式存储。</li><li>当需要为Docker创建网络环境时，通过网络管理驱动Network driver创建并配互Docker容器网络环境。</li><li>当需要限制Docker容器运行资源或执行用户指令等操作时，则通过Exec driver来完成。</li><li>Libcontainer是一项独立的容器管理包，Network driver以及Exec driver都是通过Libcontainer来实现具体对容器进行的操作。</li></ul><h2 id="架构图-入门版" tabindex="-1">架构图(入门版) <a class="header-anchor" href="#架构图-入门版" aria-label="Permalink to “架构图(入门版)”">​</a></h2><p><img src="`+i+`" alt="" width="791" height="378"></p>`,4)]])}var c=r(o,[[`render`,s]]);export{a as __pageData,c as default};